INSERT INTO pyq_collections (id, slug, subject, title, exam_paper, year, is_premium, question_count, sort_order)
VALUES ('af9dd77f-55cb-4c84-8ac3-aab600b4f01d', 'upsc-gs4-ethics-2026-pyq', 'upsc-ethics', 'UPSC GS Paper IV (Ethics) — PYQ & Model Answers (2026)', 'gs4', 2026, true, 19, 1);

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('b35c0055-2dec-4be6-913d-167befa871df', 'af9dd77f-55cb-4c84-8ac3-aab600b4f01d', 1, 'A', '1(a)', 10, 150, 'Owing to paucity of time, a university professor generates a Ph.D. evaluation report using Artificial Intelligence and submits it with some modifications. Discuss this from the perspective of accountability and integrity.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('b35c0055-2dec-4be6-913d-167befa871df', 'Using AI to draft a Ph.D. evaluation report is not inherently unethical -- AI-assisted drafting can be a legitimate efficiency tool, the same way a calculator assists arithmetic without compromising a mathematician''s conclusions. The ethical concern is not the tool itself but what accountability the professor retains for the report''s substance.

From an integrity standpoint, the professor remains the report''s author of record and bears full responsibility for its accuracy and fairness to the candidate, regardless of how it was drafted -- delegating the drafting to AI does not delegate the underlying academic judgment, which must remain genuinely the professor''s own independent assessment of the thesis''s merit, not an unreviewed AI output.

The real risk is that time pressure that motivated using AI in the first place may also produce insufficient verification of the AI-generated content before submission -- an AI evaluation tool can hallucinate specifics, misjudge nuanced academic arguments, or apply generic evaluation criteria poorly suited to a specific thesis''s actual contribution, and "some modifications" is a genuinely low bar if it means light editing rather than substantive independent verification.

Accountable practice requires disclosing AI assistance transparently (many institutions now require this), and treating the AI output as a first draft requiring the professor''s own full substantive review -- not a shortcut that transfers the underlying evaluative responsibility away from the human evaluator whose name and judgment the report represents.', 'Strong answers avoid a knee-jerk ''AI is bad'' framing and instead correctly locate the ethical issue: accountability for the evaluation''s substance remains entirely the professor''s regardless of drafting method, and the real risk is inadequate verification under time pressure, not AI use itself.', 'UPSC CSE Mains 2026, GS Paper IV, Section A, Q1(a) (exam held 23 August 2026). Verbatim text confirmed against one source (LegacyIAS''s dedicated question-paper page, quoted). Confirmed in substance (not exact wording) by two further independent sources (Drishti IAS, ForumIAS), both of which paraphrase rather than quote this section.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('b54acf6d-9cdd-4ee7-85b9-202afd291cbd', 'af9dd77f-55cb-4c84-8ac3-aab600b4f01d', 2, 'A', '1(b)', 10, 150, 'A business house is working on a project that could displace a forest community from their habitat. As the administrative officer of that district, what ethical challenges are you likely to face?');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('b54acf6d-9cdd-4ee7-85b9-202afd291cbd', 'The central ethical tension is between facilitating economic development (jobs, investment, infrastructure the project may bring) and protecting a forest community''s right to their habitat and way of life -- a right recognized in law through the Forest Rights Act''s provisions for free, prior, informed consent before diversion of forest land affecting forest-dwelling communities, which the administrative officer is bound to actually apply, not treat as a formality.

A genuine challenge is verifying whether real, informed community consent has been obtained, or whether it has been procedurally obtained but substantively coerced or inadequately explained given information and power asymmetries between a business house and a forest community -- the officer''s duty is to ensure the process is substantively fair, not merely that a signature exists.

Further challenges include ensuring rehabilitation and compensation, if displacement does proceed, is genuinely adequate (livelihood restoration, not just cash compensation that a community accustomed to forest-based subsistence cannot readily convert into an equivalent livelihood), resisting undue pressure from powerful business or political interests to expedite clearances without proper due diligence, and managing personal and institutional risk if standing firm on due process delays a project senior authorities are keen to expedite.

The officer''s role, ultimately, is to be the actual enforcement point for the community''s legal rights, not merely a procedural facilitator of the business house''s project.', 'Strong answers name the actual legal framework (Forest Rights Act''s free, prior, informed consent requirement) rather than discussing ''balancing development and community rights'' in the abstract, and identify the specific challenge of substantive versus merely procedural consent.', 'UPSC CSE Mains 2026, GS Paper IV, Section A, Q1(b) (exam held 23 August 2026). Verbatim text confirmed against one source (LegacyIAS''s dedicated question-paper page, quoted). Confirmed in substance (not exact wording) by two further independent sources (Drishti IAS, ForumIAS), both of which paraphrase rather than quote this section.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('b57ad3d6-7de1-4d0f-8264-e8c0c4e47baa', 'af9dd77f-55cb-4c84-8ac3-aab600b4f01d', 3, 'A', '2(a)', 10, 150, 'An endangered tribe has developed a severe skeletal deformity. A university research has identified a mineral supplement as a possible remedy, though clinical trials are yet to be conducted. Should the District Magistrate (DM) use this research on the tribe? Discuss from the perspective of medical and administrative ethics.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('b57ad3d6-7de1-4d0f-8264-e8c0c4e47baa', 'The DM should not authorize administering an unvalidated supplement to the tribe outside a properly conducted, ethically-approved clinical trial, however well-intentioned the underlying research and however urgent the tribe''s condition appears. Medical ethics'' core principle here is that pre-clinical or untrialed interventions carry unknown risk -- a mineral supplement identified as ''possibly'' remedial has not been tested for correct dosage, side effects, or interaction with the tribe''s existing health conditions, and administering it outside trial conditions would expose a vulnerable population to genuinely unknown harm without the safety monitoring a real trial provides.

The administrative-ethics dimension compounds this: the tribe''s endangered status and likely limited access to alternative healthcare and legal recourse make it precisely the kind of population historically vulnerable to being used as a de facto, uncontrolled test population under the guise of ''possible remedy'' -- a pattern research ethics bodies (and India''s own ICMR guidelines on tribal/vulnerable-population research) exist specifically to prevent.

The correct path is to facilitate and expedite a properly designed, ethically-approved clinical trial with genuine informed consent (through appropriate community engagement given language and literacy considerations), rather than either denying the tribe potential help entirely or bypassing trial safeguards out of urgency -- urgency does not justify skipping the very safeguards designed to prevent harm to exactly this kind of vulnerable population.', 'The correct position is a clear ''no, not outside a proper trial'' -- an answer that concludes the DM should simply administer the untrialed supplement out of urgency or compassion misses the core medical-ethics point about the actual risk of untested interventions on a vulnerable population.', 'UPSC CSE Mains 2026, GS Paper IV, Section A, Q2(a) (exam held 23 August 2026). Verbatim text confirmed against one source (LegacyIAS''s dedicated question-paper page, quoted). Confirmed in substance (not exact wording) by two further independent sources (Drishti IAS, ForumIAS), both of which paraphrase rather than quote this section.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('06d9f582-1572-4466-bada-dc509c96ef4d', 'af9dd77f-55cb-4c84-8ac3-aab600b4f01d', 4, 'A', '2(b)', 10, 150, 'Discuss how national security can be balanced with concerns of human rights.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('06d9f582-1572-4466-bada-dc509c96ef4d', 'National security and human rights are often framed as opposed, but the more accurate framing is that security measures which systematically violate human rights tend to be self-defeating over time -- alienating the very population whose cooperation security ultimately depends on, and undermining the state''s own legitimacy claim against the threats it is responding to.

Balance requires several concrete safeguards rather than treating the tradeoff as a fixed either/or. Proportionality -- security measures (surveillance, detention, use of force) should be calibrated to the actual, specific threat rather than applied as blanket measures against an entire population or community. Judicial and legislative oversight -- courts and parliamentary committees reviewing security agencies'' actions provide an accountability check that pure executive discretion lacks, reducing the risk of security powers being used beyond their legitimate purpose. Time-limited and reviewable measures -- emergency or extraordinary security powers should include sunset clauses or periodic review rather than becoming permanent, since threats and the measures justifying them both evolve.

India''s own experience with AFSPA in insurgency-affected regions illustrates the real, ongoing tension here -- a measure defended as security-necessary while facing sustained human-rights criticism over accountability gaps for actions taken under it, showing this balance is a continuous practical challenge, not a problem solved once and then settled.', 'Strong answers name specific balancing mechanisms (proportionality, oversight, sunset clauses) rather than asserting ''both matter'' generically, and a concrete Indian example (AFSPA) grounds the abstract principle in a real, ongoing policy tension.', 'UPSC CSE Mains 2026, GS Paper IV, Section A, Q2(b) (exam held 23 August 2026). Verbatim text confirmed against one source (LegacyIAS''s dedicated question-paper page, quoted). Confirmed in substance (not exact wording) by two further independent sources (Drishti IAS, ForumIAS), both of which paraphrase rather than quote this section.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('c2e19a12-b1c7-43e7-8df8-a173db1c3e7b', 'af9dd77f-55cb-4c84-8ac3-aab600b4f01d', 5, 'A', '3(a)', 10, 150, 'Dr. B. R. Ambedkar had cautioned that employing civil disobedience within a constitutional democracy equates to endorsing ''anarchy''. How should modern democracies navigate the ethical dilemmas posed by civil disobedience movements that aim to promote social justice against policies that may raise genuine concerns?');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('c2e19a12-b1c7-43e7-8df8-a173db1c3e7b', 'Ambedkar''s caution rested on a specific premise: in a functioning constitutional democracy with legitimate channels (elections, courts, free press, the right to peaceful protest itself) for grievance redressal, resorting to methods that bypass those channels risks normalizing the idea that any group dissatisfied with a democratically-arrived-at outcome may simply refuse to comply with law -- a genuinely corrosive precedent for a rules-based constitutional order if generalized without limit.

Modern democracies navigating this tension should distinguish civil disobedience''s FORM and its CONTEXT rather than applying a single blanket verdict. Peaceful, non-violent civil disobedience that operates transparently (protesters accepting legal consequences, as in the Gandhian and civil-rights-movement traditions) differs meaningfully from disobedience that employs coercion, violence, or deception -- the former operates within a framework of ultimately respecting the rule of law''s authority even while contesting a specific law''s justice, while the latter genuinely risks the anarchic slide Ambedkar warned against.

The democratic state''s responsible response is twofold: keeping legitimate redressal channels genuinely open and responsive (since disobedience movements often emerge precisely where those channels have failed to function), while still maintaining that peaceful protest is not synonymous with a license to violate law without consequence -- both extremes (suppressing all dissent, or treating any social-justice framing as exempting a movement from legal accountability) undermine the constitutional order the question asks how to protect.', 'Strong answers avoid taking a simplistic side (either fully endorsing civil disobedience as always justified, or fully endorsing Ambedkar''s caution as meaning all civil disobedience should be suppressed) and instead draw the real distinction between disobedience''s form/method and its underlying democratic legitimacy.', 'UPSC CSE Mains 2026, GS Paper IV, Section A, Q3(a) (exam held 23 August 2026). Verbatim text confirmed against one source (LegacyIAS''s dedicated question-paper page, quoted). Confirmed in substance (not exact wording) by two further independent sources (Drishti IAS, ForumIAS), both of which paraphrase rather than quote this section.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('f1d52df5-1867-4ebe-a26b-dba5e1e2d6e1', 'af9dd77f-55cb-4c84-8ac3-aab600b4f01d', 6, 'A', '3(b)', 10, 150, 'In what ways can an Indian Administrative Officer apply Gandhi''s notion of ''trusteeship'' to ensure fairness in governance?');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('f1d52df5-1867-4ebe-a26b-dba5e1e2d6e1', 'Gandhi''s trusteeship concept, originally articulated for wealthy individuals managing resources for society''s broader benefit rather than pure self-interest, translates for an administrative officer into the principle that public office and public resources are held IN TRUST for citizens, not as personal entitlement or discretionary power to be exercised for private or political benefit.

Concretely, an officer applying this principle treats public funds and welfare-scheme resources with the same or greater care as if managing one''s own family''s resources, resisting the temptation to divert or favor allocation based on personal connection rather than genuine need -- the trustee''s duty runs to the beneficiary (the citizen), not to the trustee''s own convenience or advancement.

It also implies proactive stewardship rather than mere passive compliance -- a trustee does not simply avoid actively stealing from a trust; a genuinely faithful trustee actively works to grow and protect its value for beneficiaries. Applied to governance, this means an officer should actively seek out underserved populations a scheme is meant to reach, rather than only processing whatever applications happen to arrive, and should be transparent and accountable in reporting how public resources were actually used, since a trustee owes an accounting to those the trust serves.

Finally, trusteeship implies humility about the office itself -- treating administrative power as a temporary, conditional responsibility rather than a personal achievement to be leveraged for private gain.', 'Strong answers translate the trusteeship CONCEPT concretely into administrative behavior (resource stewardship, proactive outreach, accountability, humility about power) rather than only restating Gandhi''s original economic formulation without adapting it to the specific governance context the question asks about.', 'UPSC CSE Mains 2026, GS Paper IV, Section A, Q3(b) (exam held 23 August 2026). Verbatim text confirmed against one source (LegacyIAS''s dedicated question-paper page, quoted). Confirmed in substance (not exact wording) by two further independent sources (Drishti IAS, ForumIAS), both of which paraphrase rather than quote this section.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('220bc212-c9fa-4676-b4ca-da8c13404f28', 'af9dd77f-55cb-4c84-8ac3-aab600b4f01d', 7, 'A', '3(c)', 10, 150, 'Shakespeare in Henry IV says, ''The arms are fair when the intent of bearing them is just''. What ethical implications does this have in governance?');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('220bc212-c9fa-4676-b4ca-da8c13404f28', 'The line asserts that the moral character of an instrument of power is inseparable from the intent behind its use -- the same ''arms'' (weapons, or by extension any coercive or administrative power) are ''fair'' (justified) or unfair depending entirely on the purpose they serve, not on some intrinsic property of the instrument itself.

Applied to governance, this reframes how administrative and coercive power (police authority, regulatory enforcement, emergency powers) should be ethically evaluated: the same enforcement action -- a raid, a detention, a regulatory penalty -- is ethically defensible when genuinely deployed in pursuit of legitimate public interest, and ethically indefensible when the identical action is deployed for personal vendetta, political suppression, or institutional self-protection, even though the formal legal authority for the action may be identical in both cases.

This has a direct practical implication for how an officer should self-audit the use of discretionary power: the relevant ethical question is rarely "do I have the legal authority to do this" (which is usually genuinely yes, for a wide range of administrative actions) but "is my actual intent in exercising this authority the legitimate public purpose it is meant to serve." An officer using genuine statutory power to settle a personal grievance, favor an ally, or suppress inconvenient scrutiny is misusing ''fair arms'' for an unfair intent -- the Shakespearean line''s real governance lesson is that legal authority alone never fully justifies its use; the intent behind wielding it does the remaining, decisive ethical work.', 'Strong answers connect the literary line to a specific, testable governance principle -- that legal authority and ethical justification are not the same thing, and intent is the differentiating factor -- rather than only paraphrasing the quote poetically without drawing out its administrative implication.', 'UPSC CSE Mains 2026, GS Paper IV, Section A, Q3(c) (exam held 23 August 2026). Verbatim text confirmed against one source (LegacyIAS''s dedicated question-paper page, quoted). Confirmed in substance (not exact wording) by two further independent sources (Drishti IAS, ForumIAS), both of which paraphrase rather than quote this section.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('920c7baf-f66f-466b-a0ff-15afadaebba3', 'af9dd77f-55cb-4c84-8ac3-aab600b4f01d', 8, 'A', '4(a)', 10, 150, 'Citing the serious adverse effects of long-term medication, a doctor convinces the family of a female patient for surgery. This led the patient to reluctantly consent for the surgery, though her original choice was to opt for medication. Explain the concepts of paternalism and beneficence by analysing the doctor''s action.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('920c7baf-f66f-466b-a0ff-15afadaebba3', 'Beneficence is the ethical principle that a medical professional should act in the patient''s best interest -- here, the doctor''s underlying motivation (avoiding serious long-term medication side effects) is genuinely beneficent in intent, aimed at a better health outcome for the patient.

Paternalism is what occurs when that beneficent intent is pursued by overriding or bypassing the patient''s own autonomous decision-making rather than respecting it -- and this is precisely the ethical problem in this scenario. The doctor did not persuade the PATIENT directly and secure her genuine, autonomous reconsideration; the doctor convinced her FAMILY, who then pressured her into ''reluctant'' consent. This is a textbook case of paternalism overriding autonomy through an indirect route (family pressure) rather than respecting the patient''s own capacity to weigh the medication-versus-surgery tradeoff for herself, once properly informed.

Modern medical ethics generally holds that beneficence does not license paternalism when the patient has decision-making capacity -- the correct approach was to ensure the patient herself fully understood the medication''s risks (informed consent, addressed directly to her) and to respect whichever choice she made once genuinely informed, rather than achieving the doctor''s preferred outcome through family-mediated pressure that produced only ''reluctant,'' not genuinely free, consent.

The doctor''s action, while well-intentioned (beneficent), is ethically problematic because it substituted family-mediated pressure for the patient''s own informed autonomous choice.', 'The key analytical move is identifying that consent obtained through family pressure rather than direct patient persuasion is the specific paternalism problem here -- an answer that only defines the two terms abstractly without applying them precisely to this scenario''s specific mechanism (indirect pressure via family) misses the sharpest point.', 'UPSC CSE Mains 2026, GS Paper IV, Section A, Q4(a) (exam held 23 August 2026). Verbatim text confirmed against one source (LegacyIAS''s dedicated question-paper page, quoted). Confirmed in substance (not exact wording) by two further independent sources (Drishti IAS, ForumIAS), both of which paraphrase rather than quote this section.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('0db8981a-5108-4f21-8da0-b6bdce96567f', 'af9dd77f-55cb-4c84-8ac3-aab600b4f01d', 9, 'A', '4(b)', 10, 150, 'Efficiency is doing things right, while effectiveness is doing the right thing. How do you strike a balance between the two to enhance productivity?');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('0db8981a-5108-4f21-8da0-b6bdce96567f', 'Efficiency measures how well resources (time, money, effort) are used to accomplish a given task -- doing things RIGHT, with minimal waste. Effectiveness measures whether the task itself was the correct one to pursue in the first place -- doing the RIGHT things, regardless of how efficiently they were executed. A perfectly efficient process aimed at the wrong goal produces excellent execution of a mistake; a highly effective goal pursued inefficiently wastes resources achieving something worthwhile more slowly or expensively than necessary.

Genuine productivity requires both, in the correct sequence: effectiveness should be established FIRST (identifying the right priority, policy, or intervention) before efficiency is applied to executing it well -- optimizing execution before confirming the goal is correct risks efficiently achieving the wrong outcome, a genuinely common administrative failure mode (a scheme implemented flawlessly that was never well-targeted to begin with).

In practice, striking this balance means periodically stepping back from operational execution to reassess whether current priorities remain the right ones (an effectiveness check), rather than allowing efficiency metrics (speed, cost, output volume) to become the sole measure of success, since efficiency metrics can be satisfied even while effectiveness quietly fails. A genuinely productive administrator treats effectiveness as the gate a goal must pass before efficiency is worth optimizing for.', 'Strong answers explicitly state the correct SEQUENCE (effectiveness first, then efficiency) and name the real risk of optimizing efficiency without effectiveness (efficiently achieving the wrong outcome) rather than simply defining both terms and asserting ''both matter.''', 'UPSC CSE Mains 2026, GS Paper IV, Section A, Q4(b) (exam held 23 August 2026). Verbatim text confirmed against one source (LegacyIAS''s dedicated question-paper page, quoted). Confirmed in substance (not exact wording) by two further independent sources (Drishti IAS, ForumIAS), both of which paraphrase rather than quote this section.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('a4084464-9be0-4e43-8745-0a9a428334be', 'af9dd77f-55cb-4c84-8ac3-aab600b4f01d', 10, 'A', '5(a)', 10, 150, 'Usually schools, working in remote areas, do not fully comply with government regulations. However, if the rules are enforced strictly, it would lead to most schools closing down. How should an administrator strike a balance between enforcement of rules and educational rights of children?');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('a4084464-9be0-4e43-8745-0a9a428334be', 'The underlying ethical tension is that rigid rule enforcement, applied without regard to context, can produce an outcome (school closures) that actively undermines the very right (children''s education) the regulations exist to protect -- a case where literal compliance and the regulation''s actual purpose point in opposite directions.

The administrator''s correct approach is not to choose between strict enforcement and complete non-enforcement, but to apply a graduated, purpose-driven response. First, distinguish violations by severity and impact on child safety/learning outcomes -- a school lacking a fully compliant building certificate is a different category of violation from one with a demonstrably unsafe structure or unqualified, harmful instruction; the former merits a remediation timeline, the latter may genuinely require immediate action regardless of closure risk. Second, use a time-bound improvement framework rather than an immediate closure ultimatum for non-safety-critical violations -- giving remote schools a realistic, resourced path to compliance (potentially with government support given remote areas'' real capacity constraints) rather than an unachievable immediate standard that only closure can satisfy. Third, prioritize keeping children enrolled and learning throughout this process, treating closure as the last resort only for genuinely unsafe situations, not a default enforcement tool.

The administrator''s actual duty is to the regulation''s PURPOSE (safe, quality education reaching children) not merely its LETTER, and the balance should be resolved in whichever direction better serves that underlying purpose in each specific case.', 'Strong answers propose a genuinely graduated approach (distinguishing violation severity, time-bound remediation) rather than a binary choice between ''enforce strictly'' and ''don''t enforce,'' and explicitly name the tension between literal rule compliance and the rule''s actual protective purpose.', 'UPSC CSE Mains 2026, GS Paper IV, Section A, Q5(a) (exam held 23 August 2026). Verbatim text confirmed against one source (LegacyIAS''s dedicated question-paper page, quoted). Confirmed in substance (not exact wording) by two further independent sources (Drishti IAS, ForumIAS), both of which paraphrase rather than quote this section.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('72d19da2-33e7-479a-a4e1-c1380b47317c', 'af9dd77f-55cb-4c84-8ac3-aab600b4f01d', 11, 'A', '5(b)', 10, 150, 'In international relations, ethical considerations are often subjugated to the strategic interests of nation-states. Discuss this from an ethical perspective.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('72d19da2-33e7-479a-a4e1-c1380b47317c', 'The statement reflects the realist tradition in international relations, which holds that states act primarily to maximize security and power in an anarchic international system lacking a global enforcement authority, making ethical considerations subordinate to survival-driven strategic calculation whenever the two genuinely conflict -- a state''s alliance choices, arms sales, or silence on another state''s human-rights record are frequently explicable in exactly these terms.

An ethical perspective need not simply accept this as inevitable or fully justified, however. Even within a realist framework, most states find it strategically necessary to at least frame actions in ethical/legal language (sovereignty, self-defense, human rights) because international legitimacy itself has real strategic value -- a state seen as acting purely amorally faces real reputational and coalition-building costs, meaning ethics and strategic interest are not always as separable as a pure realist framing suggests.

The more defensible ethical position is not to expect states to act purely altruistically against their own strategic interest (an unrealistic standard given the anarchic international system realists correctly describe), but to hold states accountable to a MINIMUM ethical floor even while pursuing strategic interest -- avoiding complicity in clear atrocities, honoring binding treaty commitments, and not treating ethical language as pure cover for actions with no genuine ethical constraint at all. The tension the statement describes is real, but a total abandonment of ethical constraint is neither accurate to how states actually behave nor a standard ethical analysis should simply concede.', '''Discuss ethically'' invites genuine ethical analysis, not just description of realist IR theory -- strong answers both acknowledge the realist framing''s real explanatory power AND push back with a defensible ethical minimum-floor position, rather than either fully endorsing amoral realism or naively asserting ethics should always trump strategic interest.', 'UPSC CSE Mains 2026, GS Paper IV, Section A, Q5(b) (exam held 23 August 2026). Verbatim text confirmed against one source (LegacyIAS''s dedicated question-paper page, quoted). Confirmed in substance (not exact wording) by two further independent sources (Drishti IAS, ForumIAS), both of which paraphrase rather than quote this section.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('a59306a7-df99-4472-8f88-cbff5e150c70', 'af9dd77f-55cb-4c84-8ac3-aab600b4f01d', 12, 'A', '6(a)', 10, 150, 'On the request of his Personal Assistant (PA), the District Magistrate (DM) stops the transfer of a schoolteacher who takes private tuition for his daughter diagnosed with learning disability. In this context, discuss the aspects of empathy versus compliance with rules.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('a59306a7-df99-4472-8f88-cbff5e150c70', 'The DM''s action raises a genuine tension between empathy (a compassionate response to the PA''s personal circumstance -- a child with a learning disability benefiting from a specific teacher''s tuition) and compliance with rules (the administrative transfer policy the DM is overriding, presumably established for legitimate reasons like equitable staff rotation or filling a genuine need elsewhere).

The ethical problem is not that empathy played a role in the DM''s reasoning -- a wholly rule-mechanical administrator with zero regard for genuine hardship is not thereby more ethical. The problem is that this empathetic exception was extended specifically because the affected party was the DM''s OWN PA, raising the real question of whether an identical hardship affecting an ordinary citizen with no personal connection to the DM would have received the same consideration -- if not, this is not principled empathetic flexibility but favoritism dressed in empathetic language.

The ethically defensible path is to institutionalize the empathetic exception as a GENERAL, transparent policy -- a documented hardship-transfer-deferral provision available to any employee''s family facing a comparable genuine need (a child''s diagnosed learning disability requiring continuity of a specific support arrangement), rather than an ad hoc favor granted only because of who asked. Empathy and rule-compliance are reconcilable through consistent, transparent exception criteria; they become genuinely opposed only when empathy is applied selectively based on personal proximity to power rather than the underlying merit of the hardship itself.', 'The critical ethical distinction is not empathy-versus-rules in the abstract, but whether the exception is principled and generalizable or a personal favor -- strong answers identify that the DM''s PA relationship is the actual problem, not the underlying compassionate consideration itself.', 'UPSC CSE Mains 2026, GS Paper IV, Section A, Q6(a) (exam held 23 August 2026). Verbatim text confirmed against one source (LegacyIAS''s dedicated question-paper page, quoted). Confirmed in substance (not exact wording) by two further independent sources (Drishti IAS, ForumIAS), both of which paraphrase rather than quote this section.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('7ace87a7-5c6a-4b5b-b85c-12e884fd6c18', 'af9dd77f-55cb-4c84-8ac3-aab600b4f01d', 13, 'A', '6(b)', 10, 150, 'Some moral philosophers argue that spending some of your resources — without significantly affecting your financial stability — to help other people who badly suffer is our moral duty and not merely a matter of charity. Justify this claim by explaining the distinction between duty and charity.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('7ace87a7-5c6a-4b5b-b85c-12e884fd6c18', 'Charity, in ordinary usage, is a supererogatory act -- morally praiseworthy if performed, but not morally required, meaning a person who never gives to charity has not thereby violated any moral obligation. Duty, by contrast, is morally required -- failing to fulfill a duty is a genuine moral failing, not merely a missed opportunity for extra credit.

The philosophical argument for reclassifying low-cost aid to those in severe suffering as duty rather than charity (most influentially made by Peter Singer) rests on a comparison: if a person would unquestionably be morally obligated to save a drowning child at minor cost (ruining one''s clothes) even though the child is a stranger, then the mere GEOGRAPHIC or SOCIAL distance of someone suffering severely elsewhere should not, on reflection, change the underlying moral logic -- if minor personal cost against severe suffering generates an obligation in the nearby case, the same structure arguably generates an obligation in the distant case too, since distance alone is not obviously morally relevant to whether suffering matters.

This reframing has real practical implications: if accepted, it converts what many treat as an optional, praiseworthy extra (charitable giving) into a genuine moral baseline everyone with resources to spare is failing to meet, which is precisely why the argument remains genuinely contested -- it demands far more of ordinary moral life than the conventional charity/duty distinction does, and critics reasonably question whether it demands more than is psychologically or practically sustainable as a genuine, universal moral standard.', 'The strongest answers use the actual philosophical argument''s structure (the drowning-child analogy, most associated with Peter Singer) to justify the claim, rather than simply asserting that helping others is important -- ''justify this claim'' specifically asks for the reasoning that supports treating this as duty, not just agreement with the conclusion.', 'UPSC CSE Mains 2026, GS Paper IV, Section A, Q6(b) (exam held 23 August 2026). Verbatim text confirmed against one source (LegacyIAS''s dedicated question-paper page, quoted). Confirmed in substance (not exact wording) by two further independent sources (Drishti IAS, ForumIAS), both of which paraphrase rather than quote this section.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('8163973e-12bb-440b-9b2b-28ca1d1032bd', 'af9dd77f-55cb-4c84-8ac3-aab600b4f01d', 14, 'B', '7', 20, 250, 'Lata, a mother of two children, was admitted to a hospital for acute abdominal pain. Her sister-in-law, Sujatha, accompanied her. Dr. Mansi examined Lata and recommended a diagnostic laparoscopy. Lata''s consent was taken to conduct the medical procedure under general anesthesia. During the laparoscopy, Dr. Mansi''s team discovered a tumor in Lata''s uterus. A closer examination suggested that the tumor could be malignant. One option before Dr. Mansi was to extract a sample for biopsy. In that case, if the tumor was malignant, Lata would have to undergo another surgery for removal of the uterus. An alternative was to remove the uterus immediately. Dr. Mansi had to take a quick decision. As Lata was under general anesthesia, Dr. Mansi explained the situation to Sujatha. Sujatha agreed with Dr. Mansi''s recommendations for a hysterectomy, wherein Lata''s uterus would be removed to avoid the risk and pain of undergoing another surgery. Dr. Mansi removed Lata''s uterus after receiving Sujatha''s consent in writing. Lata was informed of this the next day. She was very upset and felt betrayed as she had not consented to the removal of her uterus. Lata complained to the police who tried to convince her that Dr. Mansi had acted with good intention to help a patient. Sujatha was of the same opinion, however Lata was not convinced and decided to approach the court.

(a) Discuss the ethical issues involved in this case.
(b) Discuss the moral conduct of the doctor in this situation.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('8163973e-12bb-440b-9b2b-28ca1d1032bd', '(a) Ethical issues: This is fundamentally a case of consent violation. Lata consented specifically to a diagnostic laparoscopy under anesthesia -- she never consented to a hysterectomy, an irreversible procedure with major life consequences (loss of fertility, hormonal effects) she never had the opportunity to weigh for herself. Sujatha''s proxy consent is legally and ethically inadequate as a substitute: Sujatha is not Lata''s legal guardian or designated medical proxy, merely a relative present at the hospital, and even a genuinely well-meaning proxy cannot substitute for the patient''s own informed autonomous choice on a decision this consequential and irreversible. A second ethical issue is the false equivalence between good intent and ethical conduct -- the police''s attempt to excuse the doctor''s action purely on the basis of good intention conflates beneficence with the separate requirement of respecting autonomy; a well-intentioned violation of consent remains a violation.

(b) Moral conduct of the doctor: Dr. Mansi''s underlying medical judgment (avoiding a second surgery''s risk) may have been clinically sound, but the moral conduct in obtaining consent was seriously deficient. The correct ethical path, even under time pressure, was to complete the biopsy-only procedure Lata had actually consented to, close the surgery, and have the full malignancy-versus-hysterectomy conversation directly with Lata once she regained consciousness -- respecting her right to make this decision herself, even at the cost of a possible second surgery. Where genuine emergency truly precludes any delay, only a legally recognized next-of-kin/guardian process (not an informally present relative) with full disclosure would come closer to acceptable, and even then, this scenario''s specific severity does not appear to have been a genuine emergency precluding the delay entirely. Dr. Mansi''s conduct, therefore, prioritized clinical efficiency over the patient''s autonomy in a way that was not ethically justified by the actual urgency present.', 'Strong answers clearly identify Sujatha''s consent as legally/ethically inadequate (not a valid substitute for Lata''s own), name the good-intent-does-not-equal-ethical-conduct fallacy in the police''s response, and reach a clear, reasoned verdict on the doctor''s conduct (deficient, not merely ''complicated'') rather than staying neutral on whether the doctor acted wrongly.', 'UPSC CSE Mains 2026, GS Paper IV, Section B, Case Study Q7 (exam held 23 August 2026). Full scenario text verified verbatim, matching essentially word-for-word, between two independent sources: ForumIAS and IASbaba, both publishing the complete case-study narrative rather than a summary.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('8aaeb3c1-5606-43a6-9132-f93a15f8815a', 'af9dd77f-55cb-4c84-8ac3-aab600b4f01d', 15, 'B', '8', 20, 250, 'Ravi is a senior police officer with vast experience in riot control and cyber-policing. Since one year, he has been the Superintendent of Police (SP) of a district with a history of frequent rioting. Last year, Ravi had sought installation of an AI enabled software for predictive policing. This system has been operational for approximately six months. This system employs advanced algorithms for capturing the biometric data of persons in a crowd and swiftly relating it to a data library. This has enabled the police to identify the persons involved in various crimes. The system has identified an immigrant and low-income neighbourhood as a centre for gang violence and drug trafficking. Aided by this AI analysis, the local police has focused its patrolling, preventive detentions and establishing checkposts. Consequently, public order and law enforcement has visibly improved. Last week, some community leaders, civil rights lawyers and human rights activists visited Ravi''s office. They submitted a memorandum that the new system is faulty as it is based on incorrect historical data caused by social biases and discriminatory policing. The memorandum also alleges that the increased surveillance has created a climate of tension amongst residents. This feeling is aggravated by the fact that the residents are not aware of the data noted against their names.

(a) What are the ethical issues including biases involved in the use of AI in data-driven policing?
(b) Place yourself in Ravi''s role and discuss the alternatives available. Justify the action that optimises compliance with ethics.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('8aaeb3c1-5606-43a6-9132-f93a15f8815a', '(a) Ethical issues: The core issue is that AI predictive-policing systems trained on historical arrest and crime-report data inherit and amplify whatever biases already existed in that historical data -- if a neighbourhood was historically over-policed due to discriminatory practice, the resulting data will show elevated ''crime'' there not because actual crime rates are higher but because reporting and enforcement were higher, and the AI system then ''predicts'' more crime there, triggering more policing, in a self-reinforcing feedback loop that launders historical bias into an apparently neutral, data-driven output. A second issue is due process and transparency -- residents are not informed of the data held against them, denying them any ability to contest or correct erroneous entries, a genuine due-process gap. A third issue is the tension between visible short-term public-order improvement and long-term community trust erosion, which itself undermines effective policing (which depends on community cooperation) over time.

(b) Ravi''s alternatives and recommended action: Options range from continuing the system unchanged (ethically indefensible given the documented bias concerns), fully discontinuing it (discards genuine crime-reduction benefits and may not address the underlying data-quality issue), to a middle path: commissioning an independent bias audit of the system''s training data and algorithm, suspending its use for identifying NEW patrol/checkpost targets until that audit is complete, while maintaining current lawful policing operations, establishing a transparent, accessible process for residents to know and contest data held about them, and engaging the community leaders and civil-rights representatives directly in redesigning oversight rather than treating their memorandum as adversarial. This path optimizes ethics compliance by directly addressing the identified bias and transparency failures without abandoning legitimate public-safety gains, treating the community''s concerns as valid input to fix the system rather than an obstacle to route around.', 'Strong answers explain the SPECIFIC mechanism of AI bias (historical data encoding past discriminatory enforcement, creating a feedback loop) rather than asserting ''AI can be biased'' generically, and Ravi''s recommended action should be a genuine middle path with concrete steps (independent audit, transparency mechanism, community engagement) rather than a binary keep-it/scrap-it choice.', 'UPSC CSE Mains 2026, GS Paper IV, Section B, Case Study Q8 (exam held 23 August 2026). Full scenario text verified verbatim, matching essentially word-for-word, between two independent sources: ForumIAS and IASbaba, both publishing the complete case-study narrative rather than a summary.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('df3f6d52-dcfc-4e6e-b373-2736c2ff1c88', 'af9dd77f-55cb-4c84-8ac3-aab600b4f01d', 16, 'B', '9', 20, 250, 'Seema is a senior bureaucrat with a reputation of honesty and professional efficiency. She has recently been posted as the District Collector (DC) to Surinder Nagar, where a large industrial area is being established. The new industrial area had caused many farmers to submit applications for change of land use (CLU) to convert their farmlands into residential areas. There is an unusually large backlog of these applications awaiting processing. Seema noticed that some applications had been approved selectively with no visible chronological pattern. The case files showed a few complaints of some approvals being subject to receipt of large bribes from the applicants. On further fact-finding, Seema realized that a small group of touts was controlling this illegal activity through some subordinate officials in the Collectorate. This had created a fear in the other employees who were reluctant to process any application. The resultant backlog has been piling up thereby hindering local economic progress and causing public dissatisfaction. Seema was faced with a major moral and administrative challenge of dismantling this corruption network without hampering daily administrative operations. An aggressive internal investigation would result in institutional resistance and, possibly, a backlash from labour unions. Conversely, ignoring this situation would encourage the wrongdoers and unnecessarily continue this avoidable harassment to the populace.

(a) What are the ethical issues involved in this case?
(b) Discuss the options open to Seema. Identify the recommended option and justify it.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('df3f6d52-dcfc-4e6e-b373-2736c2ff1c88', '(a) Ethical issues: The central issue is institutionalized corruption -- touts and subordinate officials operating a bribery-for-approval racket that has captured a public administrative function for private gain. A second issue is the culture of fear this has produced among honest employees, who face a genuine moral hazard: processing applications normally risks conflict with the corrupt network, while staying silent perpetuates the harm. A third issue is Seema''s own accountability as the newly-posted DC -- she now has direct knowledge of the corruption and faces a personal integrity test in how decisively she responds, balanced against the legitimate operational risk that an aggressive crackdown disrupts an already-backlogged system further.

(b) Options and recommendation: Option one, ignore or defer action, is ethically indefensible given documented knowledge of active corruption and its clear institutional and public harm -- inaction itself becomes a form of complicity once the DC has confirmed knowledge. Option two, an immediate, aggressive, wide-scale internal crackdown, risks the institutional backlash and union resistance described, potentially paralyzing the Collectorate''s functioning entirely and providing corrupt actors an opportunity to destroy evidence during the disruption. The recommended option is a phased, evidence-based approach: quietly gather documented evidence on the specific implicated officials and touts (avoiding premature disclosure that would let them destroy records or intimidate witnesses), refer confirmed cases to the appropriate vigilance/anti-corruption authority for formal action against specific individuals rather than announcing a blanket crackdown, simultaneously introduce process reforms (a transparent, time-stamped, queue-based CLU processing system reducing officials'' discretionary opportunity for selective approval) that structurally reduces future corruption opportunity, and communicate to the broader staff that the action targets specific wrongdoers, not the department as a whole, to reduce unwarranted fear among honest employees. This targets the actual wrongdoers precisely while minimizing operational disruption and structurally reducing recurrence.', 'Strong answers reject both extremes (ignoring the corruption, and an undifferentiated blanket crackdown) in favor of a targeted, evidence-based, phased approach that also includes a structural/process fix (reducing future discretionary opportunity for corruption), not just punishing the current wrongdoers.', 'UPSC CSE Mains 2026, GS Paper IV, Section B, Case Study Q9 (exam held 23 August 2026). Full scenario text verified verbatim, matching essentially word-for-word, between two independent sources: ForumIAS and IASbaba, both publishing the complete case-study narrative rather than a summary.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('3ddced12-4c18-4bea-a085-bd6c36a4e9d6', 'af9dd77f-55cb-4c84-8ac3-aab600b4f01d', 17, 'B', '10', 20, 250, 'Vikas is a government officer with over a decade of service in public administration. He has recently moved as the District Collector (DC) of Nainipura, a remote hilly district bordering a forest. Due to Nainipura''s low levels of economic development, one of his major duties is to ensure proper functioning of the public distribution system (PDS) amongst the economically weaker sections (EWS). During his on-site visits, Vikas was apprised of a typical administrative challenge in operating the PDS. To prevent leakages, all distributors were required to carry out real-time biometric identification of the beneficiaries, whose fingerprints were tallied with identity card records. This was creating problems as the operating system sometimes rejected fingerprint matching in the cases of growing children, manual labourers and senior citizens. The problem was further compounded in periods of low WiFi connectivity. The distributors, in such cases, resorted to personal discretion when they could identify the recipient. Vikas had to address this problem on priority. Strictly adhering to government regulations would ensure fiscal probity but would greatly trouble the proposed beneficiary, i.e., EWS. It may even impinge on their fundamental right to life as per Article 21 of the Constitution. Conversely, leaving the resolution solely to the discretion of the distributors could lead to misuse and leakages.

(a) What are the options open to Vikas? How should he balance fiscal probity with empathy towards the designated beneficiaries?
(b) Discuss the ethics of using technology as a gatekeeper for welfare schemes.');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('3ddced12-4c18-4bea-a085-bd6c36a4e9d6', '(a) Options and balance: Option one, strict biometric-only compliance with no exceptions, protects against leakage but denies food access to genuinely eligible beneficiaries whose fingerprints fail to match for entirely legitimate physiological reasons (worn fingerprints from manual labour, still-developing prints in children, age-related skin changes in seniors) -- a technology failure being allowed to override a constitutional right to food/life. Option two, unrestricted distributor discretion, reopens the leakage risk the biometric system was designed to prevent. The balanced approach is a structured fallback protocol: where biometric matching fails, require an alternative verification method (the physical ration card plus a second identifier such as a local witness/village-level functionary attestation, or Aadhaar-linked mobile OTP where connectivity allows) rather than either blind acceptance or blind denial, with every fallback-verified transaction specifically logged and flagged for a periodic audit -- preserving fiscal accountability (a paper/digital trail exists for review) while ensuring a technology glitch never becomes the reason a genuinely eligible beneficiary goes without food.

(b) Ethics of technology as welfare gatekeeper: Using technology to reduce leakage is a legitimate and often effective goal, but making technology the SOLE gatekeeper -- with no fallback for its known failure modes -- ethically inverts the scheme''s purpose: a system meant to ensure food reaches the needy instead becomes a barrier that excludes some of the neediest (precisely those most likely to have workable-fingerprint difficulties: elderly, laborers, children) due to a technical limitation entirely outside their control. Ethical technology deployment in welfare delivery requires designing for graceful degradation -- a human-verifiable fallback path for every technical failure mode -- rather than treating technology''s occasional failure as an acceptable cost the most vulnerable beneficiaries alone must bear.', 'Strong answers propose a genuinely specific fallback mechanism (not just ''use discretion'') that preserves both accountability (audit trail) and access, and part (b) should draw the general ethical principle (graceful degradation, not treating tech failure as the vulnerable beneficiary''s problem) rather than only restating the specific PDS scenario.', 'UPSC CSE Mains 2026, GS Paper IV, Section B, Case Study Q10 (exam held 23 August 2026). Full scenario text verified verbatim, matching essentially word-for-word, between two independent sources: ForumIAS and IASbaba, both publishing the complete case-study narrative rather than a summary.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('1889dcf9-4f0f-4599-8b0d-6e840c7d877f', 'af9dd77f-55cb-4c84-8ac3-aab600b4f01d', 18, 'B', '11', 20, 250, 'Rajapuram is a border district. Jhara and Biru, its two major communities are in continual conflict with each other. The social fabric is fractured and demands immediate attention. Ethnic tensions between the two communities have erupted into violence resulting in a large number of deaths. The stated causes are conflicting land claims, uneven resource allocation and inadequate political representation in government bodies. Separate relief camps had to be created for the two communities. The situation is volatile and appears to be getting out of control. Rajan has been appointed as District Magistrate (DM) of Rajapuram and tasked to quickly get the situation under control. His immediate tasks include restoring administrative authority, reopening the highway and initiating peace talks. On taking over his appointment, Rajan realized that the inter-community rivalry had even seeped into the local administration and police. With functional neutrality being the immediate casualty, it had made both communities distrustful of the government. The neighbouring country could utilize the opportunity to spur insurgent activity and further aggravate the situation. Rajan favoured a controlled approach starting with opening the highway to restore food and medical supplies. He toyed with the idea of requisitioning CRPF units to help restore administrative control.

(a) Discuss the ethical issues that need to be addressed in this case.
(b) What are the options open to Rajan? Which option would ensure protection of his non-partisan image without compromising ethics?');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('1889dcf9-4f0f-4599-8b0d-6e840c7d877f', '(a) Ethical issues: The most urgent is the collapse of institutional neutrality -- local administration and police officials have themselves absorbed the communal rivalry, meaning the state''s own machinery can no longer be trusted by either community to act impartially, which is a governance failure more fundamental than the underlying land/resource dispute itself. A second issue is competing priorities under time pressure -- restoring supplies (an immediate humanitarian imperative) versus establishing durable administrative control versus initiating peace talks all compete for Rajan''s limited immediate capacity. A third is the external-security dimension -- a neighbouring country''s potential exploitation of the instability raises the stakes of delay beyond the district''s internal social fabric alone. A fourth is the equity concern of an outside CRPF deployment being perceived, rightly or wrongly, as favoring whichever community''s narrative is politically dominant, if not handled with visible even-handedness.

(b) Options and recommendation: Requisitioning CRPF units (neutral, external, not embedded in local communal ties) to restore basic order is defensible specifically because local police neutrality has already been compromised -- an external force is likely to be perceived as more even-handed than a local force widely known to be internally divided along the same communal lines, provided its deployment is visibly and genuinely even-handed across both communities'' areas. Rajan''s non-partisan image is best protected by transparent, symmetric action: opening the highway and restoring supplies to BOTH relief camps simultaneously and visibly (not sequentially, which risks a perception of favoring whichever camp is served first), publicly and identically engaging both communities'' leadership in the peace-talks initiation, and, critically, addressing the compromised local administration directly -- reassigning or retraining officials who have demonstrably taken sides, since restoring functional institutional neutrality is the precondition for any peace talks to be trusted by either side. Sequencing symmetric humanitarian relief first, external neutral security second, and genuinely balanced peace talks third gives Rajan the best chance of being perceived as impartial by both sides.', 'Strong answers name the compromised INSTITUTIONAL neutrality (not just inter-community hostility) as the deepest issue, and the recommended sequencing should explicitly explain WHY symmetric, simultaneous action across both communities is what protects Rajan''s non-partisan image, rather than just listing his tasks in the order given.', 'UPSC CSE Mains 2026, GS Paper IV, Section B, Case Study Q11 (exam held 23 August 2026). Full scenario text verified verbatim, matching essentially word-for-word, between two independent sources: ForumIAS and IASbaba, both publishing the complete case-study narrative rather than a summary. Minor wording variant noted: IASbaba''s version reads "fractured and demands immediate attention" versus ForumIAS''s "fractured and demands mending" -- an immaterial wording difference not affecting the case''s substance.');

INSERT INTO pyq_questions (id, collection_id, sort_order, section, question_number, marks, word_limit, question_text)
VALUES ('8bfd5dd8-7c3c-4bc6-a8c3-cf6d488f0d41', 'af9dd77f-55cb-4c84-8ac3-aab600b4f01d', 19, 'B', '12', 20, 250, 'Ajit has been recently promoted as the Head of the Department of Weapon Sales (DWS) in the Ministry of Defence Production (MDP). His charter of duties includes international sales of weapons produced domestically by MDP. In two recent wars, MDP weapons have performed admirably, resulting in many countries showing interest in buying them, particularly long-range artillery and missiles. Country A and country B have asked for these weapons. However, production constraints restrict DWS to accept only one purchase order. Country A is a developing nation with a sound technology base. MDP is planning R&D collaboration with it for the next generation of weapons. It is not part of any security alliance and needs weapons for protection from a troublesome neighbour. It seeks a large acquisition on a long-term loan. Country B is also a developing nation. Military strength is its priority, with the military budget often ingressing into allocations for human resources and infrastructure development. It is in security alliance with a superpower which has a large military base there and periodically allots it financial grants. It is a member of an economic bloc with which the government is currently negotiating a free trade agreement. It is not a signatory of NPT but possesses smaller nuclear weapons and their delivery systems. It supports some guerrilla forces abroad. It has sought a smaller acquisition and is prepared to make some advance payment. It is currently negotiating arms purchases from another nation too. Ajit discussed this case with his counterparts in the related departments. Therein, the significant economic benefits, employment generation and stronger diplomatic relations arising from this sale were highlighted. It was also emphasized that refusing the deal could result in country B purchasing weapons from some other supplier. Ajit was aware that in arms sales, due diligence at each stage was pivotal to ensure conformity to national policy and international treaties.

(a) Discuss the options available to Ajit. Which option should he select and why?
(b) How can Ajit balance nation''s economic and strategic interests with ethical considerations?');
INSERT INTO pyq_model_answers (question_id, model_answer, examiner_notes, source_note)
VALUES ('8bfd5dd8-7c3c-4bc6-a8c3-cf6d488f0d41', '(a) Options and recommendation: Selling to Country A supports a genuine long-term strategic and technological partnership (planned R&D collaboration), a country with no record of destabilizing behavior, and a defensive-need justification (protection from a troublesome neighbour) that aligns cleanly with legitimate arms-export purposes. Selling to Country B offers larger immediate economic incentives (advance payment, FTA-linked economic-bloc relationship, diplomatic goodwill with its allied superpower) but carries serious red flags: it is a non-NPT nuclear-capable state, it supports guerrilla forces abroad (raising real proliferation and conflict-fueling concerns inconsistent with responsible arms-export conduct), and it is simultaneously negotiating with other suppliers, meaning the ''lose the deal entirely'' argument is speculative pressure rather than certain fact. On balance, Ajit should recommend Country A: the ethical red flags attached to Country B (nuclear proliferation risk, support for guerrilla forces, i.e., non-state armed groups) are serious enough that responsible arms-export due diligence should weigh them above the larger but ethically compromised economic benefit Country B offers.

(b) Balancing economic/strategic interests with ethics: The correct framework is not to treat economic and strategic benefit as automatically overriding ethical due diligence, nor to treat ethics as an absolute bar ignoring all strategic benefit -- it is to apply a genuine screening threshold before economic considerations are weighed at all: does the recipient''s profile (proliferation risk, support for non-state armed conflict, human-rights record, end-use assurance reliability) pass a minimum responsible-conduct bar. Only among options that clear this ethical screening threshold should the economic and strategic benefits then be compared and optimized. Country B''s guerrilla-force support and non-NPT nuclear status arguably fail this initial threshold regardless of its superior economic terms, meaning the ethical screening should be applied FIRST, with economic optimization only relevant among the remaining, ethically acceptable options -- Country A in this case.', 'Strong answers reach a clear, justified recommendation (Country A) rather than listing pros and cons of both without a verdict, and part (b) should articulate the correct DECISION SEQUENCE explicitly -- ethical screening first, economic optimization only among ethically acceptable options -- rather than describing balancing the two considerations vaguely.', 'UPSC CSE Mains 2026, GS Paper IV, Section B, Case Study Q12 (exam held 23 August 2026). Full scenario text verified verbatim, matching essentially word-for-word, between two independent sources: ForumIAS and IASbaba, both publishing the complete case-study narrative rather than a summary.');
